import type { Firestore, Transaction } from "firebase-admin/firestore";
import type { PublicReleasePair } from "../../packages/content-core/src/public-release";
import type { PairTaskIdentity } from "./public-release-pair-work";
import type { PairViewCursor } from "./public-release-pair-view";
import type { PairAuthorOwner } from "./public-release-pair-author";
export type PairCompositeRole = "route" | "search" | "content-feed" | "catalog" | "auxiliary";
export type PairCompositeMember = Readonly<{ path: string; role: PairCompositeRole; kind: string; status: 200 | 302 | 308 | 410;
  mime: string; size: number; sha256: string; sourceDependencyDigest: string; owner?: PairAuthorOwner }>;
export type PairCompositeAuthority = Readonly<{ baselineInputManifestDigest: string; baselineCodePackManifestDigest: string;
  baselineViewManifestDigest: string; codeAssetManifestDigest: string; sourceDependencyDigest: string; sourceCensusDigest: string; searchInputDigest: string; staticTargetDigest?: string }>;
export type PairCompositeManifest = Readonly<{ schemaVersion: 1; kind: "pair-composite-manifest"; pairDigest: string;
  inputManifestDigest: string; cursor: PairViewCursor; authority: PairCompositeAuthority; members: readonly PairCompositeMember[] }>;
export type PairCompositeProof = Readonly<{ schemaVersion: 1; kind: "pair-composite-proof"; status: "staged"; pairDigest: string;
  taskId: string; identity: PairTaskIdentity; claimDigest: string; viewManifestDigest: string; viewReadbackDigest: string;
  inputManifestDigest: string; snapshotDigest: string; cursor: PairViewCursor; descriptor: Readonly<{ digest: string; key: string; bytes: number }>;
  outputCount: number; outputBytes: number; routeCount: number; authority: PairCompositeAuthority }>;
export function publicReleasePairCompositeAuxiliaryMime(kind: string): string | null;
export function publicReleasePairCompositeAuxiliaryKind(path: string): string | null;
export function parsePublicReleasePairCompositeManifest(value: unknown, pair: PublicReleasePair, identity: PairTaskIdentity, cursor?: PairViewCursor): PairCompositeManifest;
export function publicReleasePairCompositeManifestDigest(value: PairCompositeManifest): string;
export function publicReleasePairCompositeProofPath(pair: PublicReleasePair, digest: string): string;
export function parsePublicReleasePairCompositeProof(value: unknown, pair: PublicReleasePair, identity: PairTaskIdentity, claimDigest: string, viewManifestDigest: string): PairCompositeProof;
export function assertReadPublicReleasePairCompositeInTransaction(args: { firestore: Firestore; transaction: Transaction; pair: PublicReleasePair;
  identity: PairTaskIdentity; claimDigest: string; viewManifestDigest: string; manifest: unknown; manifestDigest: string }): Promise<PairCompositeProof>;
